async function handleSlashSchedule(sc: SlashContext): Promise<void> {
  const { argsStr, rest, command, cmd } = sc;
  const sub = rest[0]?.toLowerCase();
  if (!sub || sub === 'list') {
    const schedules = loadSchedules();
    if (schedules.length === 0) {
      console.log();
      console.log(`  ${dim('Nenhum agendamento. Crie com:')}`);
      console.log(`  ${cyan('/schedule add <nome> "<cron>" <comando>')}`);
      console.log(`  ${dim('Exemplo:')} ${cyan('/schedule add nightly-audit "0 2 * * *" /analyze --audit')}`);
      console.log();
    } else {
      console.log();
      console.log(`  ${chalk.white.bold('Agendamentos')}`);
      console.log();
      for (const s of schedules) {
        const status = s.enabled ? green('✓') : dim('✗');
        const next = s.nextRunAt ? new Date(s.nextRunAt).toLocaleString('pt-BR') : '—';
        console.log(`  ${status} ${cyan(s.name)} ${dim(`[${s.cron}]`)}`);
        console.log(`    ${dim('cmd:')}  ${s.command}`);
        console.log(`    ${dim('next:')} ${next}`);
        if (s.lastRunAt) console.log(`    ${dim('last:')} ${new Date(s.lastRunAt).toLocaleString('pt-BR')}`);
      }
      console.log();
    }
  } else if (sub === 'add' && rest.length >= 4) {
    const name = rest[1];
    // Extract quoted cron
    const match = argsStr.match(/^add\s+\S+\s+"([^"]+)"\s+(.+)$/) || argsStr.match(/^add\s+\S+\s+'([^']+)'\s+(.+)$/);
    if (!match) {
      console.log(`  ${yellow('!')} Uso: ${cyan('/schedule add <nome> "<cron>" <comando>')}`);
      return;
    }
    const cron = match[1];
    const command = match[2];
    const sched = addSchedule(name, cron, command);
    const next = sched.nextRunAt ? new Date(sched.nextRunAt).toLocaleString('pt-BR') : '—';
    console.log(`  ${green('✓')} Agendamento ${cyan(name)} criado. Proxima execucao: ${next}`);
  } else if (sub === 'remove' && rest[1]) {
    const ok = removeSchedule(rest[1]);
    console.log(ok ? `  ${green('✓')} Removido` : `  ${yellow('!')} Nao encontrado`);
  } else if ((sub === 'enable' || sub === 'disable') && rest[1]) {
    const ok = toggleSchedule(rest[1], sub === 'enable');
    console.log(ok ? `  ${green('✓')} ${sub === 'enable' ? 'Habilitado' : 'Desabilitado'}` : `  ${yellow('!')} Nao encontrado`);
  } else if (sub === 'daemon') {
    const action = rest[1]?.toLowerCase();
    const { installDaemon, uninstallDaemon, daemonStatus } = require('../daemon');
    if (action === 'install') {
      const r = installDaemon();
      console.log(r.ok ? `  ${green('✓')} ${r.message}` : `  ${yellow('!')} ${r.message}`);
    } else if (action === 'uninstall' || action === 'remove') {
      const r = uninstallDaemon();
      console.log(r.ok ? `  ${green('✓')} ${r.message}` : `  ${yellow('!')} ${r.message}`);
    } else {
      const s = daemonStatus();
      console.log(`  ${dim('Status:')} ${s.installed ? (s.running ? green('ativo') : yellow('parado')) : dim('nao instalado')}`);
      console.log(`  ${dim(s.message)}`);
      console.log();
      console.log(`  ${dim('Uso:')} ${cyan('/schedule daemon install|uninstall|status')}`);
      console.log(`  ${dim('Daemon roda')} ${cyan('makestudio scheduled-run')} ${dim('a cada 60s via launchd/systemd.')}`);
    }
  } else if (sub === 'next' && rest[1]) {
    try {
      const next = computeNextRun(rest.slice(1).join(' '));
      console.log(`  ${dim('Proxima execucao:')} ${cyan(new Date(next).toLocaleString('pt-BR'))}`);
    } catch {
      console.log(`  ${yellow('!')} Cron invalido`);
    }
  } else {
    console.log(`  ${dim('Uso:')}`);
    console.log(`    ${cyan('/schedule list')}`);
    console.log(`    ${cyan('/schedule add <nome> "<cron>" <comando>')}`);
    console.log(`    ${cyan('/schedule remove <nome>')}`);
    console.log(`    ${cyan('/schedule enable|disable <nome>')}`);
    console.log(`    ${cyan('/schedule next "<cron>"')}`);
  }
}

async function handleSlashSkills(sc: SlashContext): Promise<void> {
  const { ctx } = sc;
  const skills = loadAllSkills(ctx.cwd);
  if (skills.length === 0) {
    console.log();
    console.log(`  ${dim('Nenhuma skill encontrada.')}`);
    console.log(`  ${dim('Crie skills em')} ${cyan('~/.makestudio/skills/')} ${dim('ou')} ${cyan('.makestudio/skills/')}`);
    console.log(`  ${dim('Formato: arquivo .md com YAML frontmatter.')}`);
    console.log();
  } else {
    console.log();
    console.log(`  ${chalk.white.bold('Skills disponiveis')}`);
    console.log();
    for (const s of skills) {
      const src = s.source === 'project' ? dim('[project]') : dim('[user]');
      console.log(`  ${cyan('/' + s.name)} ${src} ${dim('—')} ${s.description}`);
    }
    console.log();
    console.log(`  ${dim('Execute com')} ${cyan('/<nome>')} ${dim('ou')} ${cyan('/<nome> arg1 arg2')}`);
    console.log();
  }
}


export const AGENT_SLASH_COMMANDS: SlashCommand[] = [
  { names: ['/plan'], handler: handleSlashPlan },
  { names: ['/coordinator'], handler: handleSlashCoordinator },
  { names: ['/output-style'], handler: handleSlashOutputStyle },
  { names: ['/memory', '/mem'], handler: handleSlashMemory },
  { names: ['/mcp'], handler: handleSlashMcp },
  { names: ['/agents'], handler: handleSlashAgents },
  { names: ['/agent'], handler: handleSlashAgent },
  { names: ['/output-style', '/ostyle'], handler: handleSlashOutputStyle81 },
  { names: ['/permission-mode', '/pmode'], handler: handleSlashPermissionMode },
  { names: ['/schedule'], handler: handleSlashSchedule },
  { names: ['/skills'], handler: handleSlashSkills },
];
